import { Component } from './Component';
import { ensureElement } from '../utils/utils';
export class Page extends Component {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._wrapper = ensureElement('.page__wrapper', this.container);
        this._gallery = ensureElement('.gallery', this.container);
        this._basket = ensureElement('.header__basket', this.container);
        this._counter = ensureElement('.header__basket-counter', this.container);
        this._basket.addEventListener('click', () => {
            this.events.emit("basket:opened" /* EventsEnum.BasketOpened */);
        });
    }
    set gallery(items) {
        this._gallery.replaceChildren();
        items.forEach(item => this._gallery.appendChild(item));
    }
    set counter(value) {
        this._counter.textContent = value.toString();
    }
    set locked(value) {
        if (value) {
            this._wrapper.classList.add('page__wrapper_locked');
        }
        else {
            this._wrapper.classList.remove('page__wrapper_locked');
        }
    }
}
